const books=[['Genesis',50,'GEN'],['Exodus',40,'EXO'],['Leviticus',27,'LEV'],['Numbers',36,'NUM'],['Deuteronomy',34,'DEU'],['Joshua',24,'JOS'],['Judges',21,'JDG'],['Ruth',4,'RUT'],['1 Samuel',31,'1SA'],['2 Samuel',24,'2SA'],['1 Kings',22,'1KI'],['2 Kings',25,'2KI'],['1 Chronicles',29,'1CH'],['2 Chronicles',36,'2CH'],['Ezra',10,'EZR'],['Nehemiah',13,'NEH'],['Esther',10,'EST'],['Job',42,'JOB'],['Psalms',150,'PSA'],['Proverbs',31,'PRO'],['Ecclesiastes',12,'ECC'],['Song of Solomon',8,'SNG'],['Isaiah',66,'ISA'],['Jeremiah',52,'JER'],['Lamentations',5,'LAM'],['Ezekiel',48,'EZK'],['Daniel',12,'DAN'],['Hosea',14,'HOS'],['Joel',3,'JOL'],['Amos',9,'AMO'],['Obadiah',1,'OBA'],['Jonah',4,'JON'],['Micah',7,'MIC'],['Nahum',3,'NAM'],['Habakkuk',3,'HAB'],['Zephaniah',3,'ZEP'],['Haggai',2,'HAG'],['Zechariah',14,'ZEC'],['Malachi',4,'MAL'],['Matthew',28,'MAT'],['Mark',16,'MRK'],['Luke',24,'LUK'],['John',21,'JHN'],['Acts',28,'ACT'],['Romans',16,'ROM'],['1 Corinthians',16,'1CO'],['2 Corinthians',13,'2CO'],['Galatians',6,'GAL'],['Ephesians',6,'EPH'],['Philippians',4,'PHP'],['Colossians',4,'COL'],['1 Thessalonians',5,'1TH'],['2 Thessalonians',3,'2TH'],['1 Timothy',6,'1TI'],['2 Timothy',4,'2TI'],['Titus',3,'TIT'],['Philemon',1,'PHM'],['Hebrews',13,'HEB'],['James',5,'JAS'],['1 Peter',5,'1PE'],['2 Peter',3,'2PE'],['1 John',5,'1JN'],['2 John',1,'2JN'],['3 John',1,'3JN'],['Jude',1,'JUD'],['Revelation',22,'REV']];
const special=[{title:'When God Feels Silent',ref:'Psalm 13',theme:'Trust',read:['Psalm 13'],understand:'David brings honest grief to God: he names the silence he feels, asks for help, and chooses to remember God’s steadfast love. The psalm does not tell us which crisis prompted it. Its movement from lament to trust gives us language for seasons when circumstances have not yet changed.',cross:['1 Samuel 23:14','Psalm 22:1','Psalm 42:5','Psalm 56:3','Habakkuk 1:2','Romans 8:31']},{title:'Known Before You Speak',ref:'Psalm 139:1–18',theme:'God’s care',read:['Psalm 139:1','Psalm 139:13'],understand:'The psalm celebrates God’s complete knowledge and nearness. Being known by God can bring comfort, awe, and an invitation to walk honestly before him.',cross:['Jeremiah 1:5','Matthew 10:29','John 10:14']},{title:'Joy That Survives Hardship',ref:'Philippians 4:4–13',theme:'Joy',read:['Philippians 4:4','Philippians 4:10'],understand:'Paul writes about joy, prayer, contentment, and strength while facing real pressure. Christian joy is not denial of hardship; it grows from confidence in Christ.',cross:['Psalm 16:8','John 15:11','1 Thessalonians 5:16']},{title:'Forgiveness Without Scorekeeping',ref:'Matthew 18:21–35',theme:'Mercy',read:['Matthew 18:21','Matthew 18:28'],understand:'Jesus answers Peter’s question about repeated forgiveness with a story about mercy received and mercy extended. Forgiveness matters because we live by grace.',cross:['Ephesians 4:32','Colossians 3:13','Luke 17:3']}];
const total=books.reduce((n,b)=>n+b[1],0),key='oyw-progress-v1';let state=JSON.parse(localStorage.getItem(key)||'{}');if(!state.done)state.done={};if(!state.notes)state.notes={};let activeDay=Number(state.lastDay||1),view='today';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function dayChapters(day){if(day<=4)return special[day-1].read;const start=Math.floor((day-5)*(total)/(361)),end=Math.floor((day-4)*(total)/(361));let ix=1;const out=[];for(const [name,count,code] of books){for(let c=1;c<=count;c++,ix++){if(ix>start&&ix<=end)out.push({name,code,chapter:c})}}return out.map(c=>c.name+' '+c.chapter)}
function plan(day){if(day<=4)return special[day-1];const read=dayChapters(day);const theme=['Trust','Wisdom','Prayer','Hope','Service','Gratitude'][day%6];const main=read[0]||'Genesis 1';return {title:'The Word for Today',ref:read.join(' · '),theme,read,understand:'Read the passage in its setting. Notice what it reveals about God, what it says to its first hearers, and how it shapes faithful living today. Let the whole passage guide your understanding rather than pulling a single line out of context.',cross:[main,'Psalm 119:105','James 1:22']}}
function chapterRef(ref){const m=ref.match(/^(.+?)\s+(\d+)(?::(\d+))?$/);if(!m)return null;const b=books.find(x=>x[0]===m[1]);return b?'https://www.bible.com/bible/59/'+b[2]+'.'+m[2]+'.ESV':null}
function readLinks(items){return items.map(r=>'<a href="'+(chapterRef(r)||'https://www.bible.com/bible/59/PSA.13.ESV')+'" target="_blank" rel="noopener">'+esc(r)+' · ESV ↗</a>').join('')}
function completed(){return Object.keys(state.done).filter(k=>state.done[k]).length}
function save(){localStorage.setItem(key,JSON.stringify(state));}
function header(d,p){return '<div class="day-head"><div><p class="eyebrow">DAY '+d+' OF 365 · ABOUT 30 MINUTES · '+esc(p.theme.toUpperCase())+'</p><h1>'+esc(p.title)+'</h1><div class="reading-ref">'+esc(p.ref)+' · ESV</div></div><div class="day-controls"><button id="prev" '+(d<=1?'disabled':'')+'>← Previous day</button><button id="next">Next day →</button></div></div>'}
function progressHtml(){const n=completed(),pct=Math.round(n/365*100);return '<div class="progressbox"><div class="progressrow"><span>YOUR JOURNEY</span><span>'+pct+'% complete</span></div><div class="bar"><span style="width:'+pct+'%"></span></div><strong>'+n+' of 365 devotionals read</strong></div>'}
function renderToday(){const p=plan(activeDay),note=state.notes[activeDay]||'';$('todayView').innerHTML=header(activeDay,p)+progressHtml()+'<article class="card"><p class="eyebrow">READ · 10 MINUTES</p><h2>'+esc(p.ref)+'</h2><p class="muted">Open today’s assigned passages in the ESV. Reading links go to Bible.com.</p><div class="read-links">'+readLinks(p.read)+'</div></article><article class="card"><p class="eyebrow">UNDERSTAND · 12 MINUTES</p><h2>Setting, meaning, and connections</h2><h3>READ IN CONTEXT</h3><p>'+esc(p.understand)+'</p><h3>HOW THE PASSAGE MOVES</h3><p>Read · Notice the speaker, audience, setting, and repeated ideas. Reflect · Ask what the passage meant in its original context. Respond · Consider how its truth shapes your trust, choices, and care for others.</p><h3>CROSS-REFERENCES WORTH READING</h3><div class="cross-links">'+readLinks(p.cross)+'</div><h3>KEY IDEA</h3><p>God’s Word gives us truth for worship, wisdom, and everyday faithfulness.</p></article><article class="card"><p class="eyebrow">REFLECT · 5 MINUTES</p><h2>Heart Check</h2><p>Let this passage examine you. Answer honestly before moving on.</p><ol class="questions"><li>What stands out about God’s character in this reading?</li><li>What question or concern do you want to bring to God?</li><li>What is one faithful step you can take today?</li></ol></article><article class="card"><p class="eyebrow">RESPOND · 3 MINUTES</p><h2>Prayer and notes</h2><p>Father, help me hear your Word clearly, trust what is true, and live it with love today.</p><label for="note">What do you want to remember?</label><textarea class="note-area" id="note" placeholder="Write a reflection or prayer…">'+esc(note)+'</textarea><p class="saved" id="saved">Saved automatically on this device.</p></article><button id="mark" class="complete">'+(state.done[activeDay]?'✓ Completed':'Mark today complete')+'</button><h2 class="eyebrow" style="margin-top:26px">COMING UP</h2><div class="upcoming">'+[1,2,3].map(i=>{const d=Math.min(365,activeDay+i),q=plan(d);return '<button class="daylink" data-day="'+d+'"><strong>Day '+d+' · '+esc(q.title)+'</strong>'+esc(q.ref)+'</button>'}).join('')+'</div>';
document.getElementById('prev').onclick=()=>go(activeDay-1);document.getElementById('next').onclick=()=>go(Math.min(365,activeDay+1));document.getElementById('mark').onclick=()=>{state.done[activeDay]=!state.done[activeDay];save();renderToday()};document.getElementById('note').oninput=e=>{state.notes[activeDay]=e.target.value;save();document.getElementById('saved').textContent='Saved automatically on this device.'};document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>go(Number(b.dataset.day)))}
function renderPlan(){$('planView').innerHTML='<div class="day-head"><div><p class="eyebrow">365 DAYS · READ AT YOUR PACE</p><h1>Year plan</h1><div class="reading-ref">'+completed()+' days complete</div></div></div>'+progressHtml()+'<p class="muted">Choose a day to open its reading and reflection. Your progress saves in this browser.</p><div class="plan-grid">'+Array.from({length:365},(_,i)=>'<button class="plan-day '+(state.done[i+1]?'done ':'')+(i+1===activeDay?'current':'')+'" data-pday="'+(i+1)+'" title="'+esc(plan(i+1).ref)+'">Day '+(i+1)+'</button>').join('')+'</div>';document.querySelectorAll('[data-pday]').forEach(b=>b.onclick=()=>{go(Number(b.dataset.pday));setView('today')})}
function renderNotes(){const entries=Object.entries(state.notes).filter(x=>x[1].trim()).sort((a,b)=>Number(a[0])-Number(b[0]));$('notesView').innerHTML='<div class="day-head"><div><p class="eyebrow">PRIVATE · SAVED ON THIS DEVICE</p><h1>My notes</h1><div class="reading-ref">'+entries.length+' saved reflections</div></div></div>'+(entries.length?'<div class="notes-list">'+entries.map(([d,n])=>'<article class="note-item"><h3>Day '+d+' · '+esc(plan(Number(d)).title)+'</h3><p>'+esc(n).replace(/\n/g,'<br>')+'</p><button class="action" data-note-day="'+d+'">Open devotional</button></article>').join('')+'</div>':'<article class="card"><h2>Your reflections will appear here</h2><p class="muted">Notes are saved only in this browser. Open today’s devotional and write in the notes area.</p></article>');document.querySelectorAll('[data-note-day]').forEach(b=>b.onclick=()=>{go(Number(b.dataset.noteDay));setView('today')})}
function setView(v){view=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===v));['today','plan','notes'].forEach(x=>$(x+'View').hidden=x!==v);if(v==='today')renderToday();if(v==='plan')renderPlan();if(v==='notes')renderNotes()}
function go(d){activeDay=Math.min(365,Math.max(1,d));state.lastDay=activeDay;save();renderToday()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));renderToday();
